With this in mind, you are tasked to prove the following target statement.

Target Problem (your task):

\begin{lemma}[Strictly positive caps]
    \label{lemma:tree-lipschitz-cap-lb}
    Let $embedding$ be the output of the Build-Clean-Tree algorithm, with $embedding$ of length $|H|=8\log(n)$, \underline{where all $M(x)>0$}. For every fixed pair of nodes $x_i$ and $x_j$,
    \begin{align*}
    &\text{(1)  } \Pr\left[\|\embed[i]-\embed[j]\|_1 \le \dlcap{M}(x_i, x_j)\right] =1.\\
    &\text{(2)  } \E\left[\|\embed[i]-\embed[j]\|_1\right]  \ge \Omega(1)\cdot \dlcap{M}(x_i, x_j).
    \end{align*}
\end{lemma}

ground_truth_solution:
We start by proving the following 2 auxiliary statements:

\begin{claim}[Complete cleaning]\label{claim:clean}
At time $x$ immediately after processing an entire clean stage (i.e., the last $\lc$ edges were ``clean'' edges), $\embed[x] = 0^{|H|}$.
\end{claim}
\begin{proof}
    Suppose this invariant holds at the end of every complete clean stage before the clean stage we are currently considering (or at initialization, if there is none.) Then, at the start of this clean stage, any coordinate that is nonzero must be exactly $\ell(e_{\mathcal{B}})$ for one of the at most $\lb$ ``build" edges $e_{\mathcal{B}}$ in the immediately preceding build stage---namely, there are at most $\lb$ such nonzero coordinates. We aim to show that there are at least $2 \lb$ edges with weight $\ge \max_{e_{\mcB}}\frac{\ell(e_{\mathcal{B}})}{2}$ in the clean stage, as this would immediately imply that all coordinates were cleaned. To show this, note how, by definition of the modified tree decomposition and the caterpillar property, all but $\log(n)$ of the edges $e_{\mcC}$ in the clean stage must exactly satisfy $\ell(e_{\mathcal{C}}) = \frac{M(s(e_{\mathcal{C}}))}{100 \log(n)}$. Moreover, for any $e_{\mcB}$, $\ell(e_{\mathcal{B}}) \le \frac{M(s(e_{\mathcal{B}}))}{100 \log(n)}$. Then, note how any build edge $e_{\mathcal{B}}$ is within a path of length $\lb + \lc$ of each clean edge $e_{\mathcal{C}}$, and so by \Cref{claim:path-similar}, 
    $$
    \frac{M(s(e_{\mathcal{B}}))}{M(s(e_{\mathcal{C}}))} \le e^{\frac{\lb + \lc}{50 \log(n)}} \le e^{13/50} \le 2.
    $$
    Thus, at least $\lc-\log(n)=8\log(n)\ge 2\lb$ many ``clean" edges have length that is at least half of every build edge $e_{\mcB}$. \end{proof}

\begin{claim}[Embedding has small norm]
    \label{claim:norm-bound-after-clean}
    At any location $x$, $\|\embed[x]\|_1 \le \frac{M(x)}{2}.$
\end{claim}
\begin{proof}
    By \Cref{claim:clean}, any nonzero coordinate of $\embed[x]$ must correspond to one of the $\lb$ build edges among the previous $\lb+\lc$ edges processed. Any of the at most $\lb$ build edges $e$ must satisfy:
    \begin{align}
        \ell(e)
        & \le \frac{M(s(e))}{100 \log(n)} \\
        & = \frac{M(x)}{100 \log(n)} \cdot \frac{M(s(e)}{M(x)} \\
        & \le \frac{M(x)}{100 \log(n)} \cdot e^{\frac{\lb + \lc}{50 \log(n)}} \label{step:use-path} \\ 
        & \le \frac{M(x)}{100 \log(n)} \cdot e^{13/50} \\ 
        & \le \frac{M(x)}{50 \log(n)} 
    \end{align}

    Here, \Cref{step:use-path} uses \Cref{claim:path-similar}. Accordingly, each of the $\le \lb$ nonzero coordinates of $\embed[x]$ is at most $\frac{M(x)}{50 \log(n)}$, and so,
    \begin{align}
        \|\embed[x]\|_1
        & \le \lb \cdot \frac{M(x)}{50 \log(n)} \\ 
        & \le \frac{M(x)}{2}.
    \end{align}
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
     We first prove part(1). Because of the way the build-clean procedure works, the embeddings as we move continuously along the tree are coordinate-wise Lipschitz, and only ever capture distance in one coordinate along adjacent locations. This immediately gives us that $\|\embed[i]-\embed[j]\|_1 \le d(x_i,x_j)$. What remains is to show that $\|\embed[i]-\embed[j]\|_1 \le \max\left(M(x_i),M(x_j)\right)$. This follows from \Cref{claim:norm-bound-after-clean}, because \begin{align*}
        \|\embed[x] - \embed[y]\|_1 &\le \|\embed[x]\|_1 + \|\embed[y]\|_1 \\
        &\le \frac{M(x) + M(y)}{2} \le \max(M(x),M(y)).
    \end{align*}
    Next, we turn our attention towards proving part (2). Without loss of generality, let us assume $M(i) \ge M(j)$---if this is not the case, we simply swap $x_i$ and $x_j$.

    \textbf{Case 1:} $\frac{M(i)}{M(j)} \le 2$. In this case, the caps of $x_i$ and $x_j$ are similar. Note how then:
    \begin{align}
        \dlcap{M}(x_i, x_j) &=\min(\ell(P_{i \rightarrow L})+\ell(P_{L \rightarrow j}),\max(M(i),M(j))) \\
        &=\min(\ell(P_{i \rightarrow L})+\ell(P_{L \rightarrow j}),M(i)) \label{eqn:case1-start}\\
        & \le \min(\ell(P_{i \rightarrow L}),M(i)) + \min(\ell(P_{L \rightarrow j}),M(i)) \\
        & \le \min(\ell(P_{i \rightarrow L}), M(i)) + \min(\ell(P_{L \rightarrow j}),2 \cdot M(j)) \label{eqn:mi-mj-bound}\\
        &\le \min(\ell(P_{i \rightarrow L}), M(i)) + 2\min(\ell(P_{L \rightarrow j}), M(j)).\label{eqn:case1-end}
    \end{align}
    In \Cref{eqn:mi-mj-bound}, we used the assumption that $M(i)\le 2M(j)$ under the present case. Accordingly then, we can just show that $E[\|\embed[i]-\embed[j]\|_1] \ge \Omega(1) \cdot \min(\ell(P_{i \rightarrow L}), \cdot M(i)), \Omega(1) \cdot \min(\ell(P_{L \rightarrow j}),\cdot M(j))$. This immediately follows from \Cref{subclaim:leg}.

    \textbf{Case 2:} $\ell(P_{L \rightarrow i}) \ge \frac{M(i)}{100}$. In this case,  by \Cref{subclaim:leg}, we know 
    $$E[\|\embed[i]-\embed[j]\|_1] \ge \Omega(1) \cdot \min(\ell(P_{L \rightarrow i}), M(i)) \ge \Omega(1)\cdot\frac{M(i)}{100} \ge \Omega(1)\cdot \dlcap{M}(x_i,x_j),$$
    where in the last inequality, we used that $M(i) \ge \dlcap{M}(x_i, x_j).$

    \textbf{Case 3:} $\frac{M(i)}{M(j)} >2$ and $\ell(P_{L \rightarrow i}) < \frac{M(i)}{100}$. This is the only case that remains. Our proof for this case will focus on showing (i) there must be the the end of a clean stage within $P_{L \rightarrow j}$, (ii) given that there is a clean stage that ends in $P_{L\rightarrow j}$, $\E[\|\embed[i]-\embed[j]\|_1] \ge \Omega(1) \cdot \E[\|\embed[i]\|_1]$, and finally, (iii) $\E[\|\embed[i]\|_1] = \Omega(1) \cdot M(i)$---together these imply that $\E[\|\embed[i]-\embed[j]\|_1] = \Omega(1) \cdot M(i) = \Omega(1) \cdot \dlcap{M}(i,j)$, as required.

    For (i):
    \begin{subclaim}\label{subclaim:must-clean}
        $P_{L \rightarrow j}$ contains at least $\lb + \lc$ edges, and hence, the end of a clean stage.
    \end{subclaim}
    \begin{proof}
        Note how 
        \begin{align*}
        \ell(P_{L \rightarrow j}) &= \ell(P_{i \rightarrow j})-\ell(P_{L \rightarrow i}) \\
        &\ge |M(i)-M(j)| - \ell(P_{L \rightarrow i}) \\
        &\ge \frac{M(i)}{2} - \frac{M(i)}{100} = \frac{49M(i)}{100} \\
        &> \frac{49M(j)}{50}.
        \end{align*}
        Now, there \textit{must} be the end of a clean stage in $P_{L \rightarrow j}$ if $P_{L \rightarrow j}$ contains at least $\lb + \lc$ edges. We will show that if the number of edges in $P_{L \rightarrow j}$ is smaller than $\lb +\lc$, then such a small number of edges could not possibly produce such a large $\ell(P_{L \rightarrow j})$. In particular, if so, by \Cref{claim:path-similar}, each edge $e$ of the $< \lb + \lc$ edges nearest to $x_j$ in the direction of $L$ must be of length 
        \begin{align*}
            \ell(e) \le \frac{M(j)}{100 \log(n)} \cdot \frac{M(s(e))}{M(j)} \le \frac{M(j)}{100 \log(n)} \cdot e^{\frac{\lb + \lc}{50 \log(n)}} \le \frac{M(j)}{100 \log(n)} \cdot e^{13/50} \le \frac{M(j)}{50}.
        \end{align*}
        The total length of $< \lb+\lc$ such edges on $P_{L \rightarrow j}$ would then be bounded as 
        $$\ell(P_{L \rightarrow j}) < (\lb + \lc) \cdot \ell(e) \le 13 \log(n) \cdot \frac{M(j)}{50 \log(n)} \le \frac{13}{50} \cdot M(j) < \frac{49}{50} \cdot M(j) < \ell(P_{L \rightarrow j}),$$ causing a contradiction.
    \end{proof}

    For (ii):
    \begin{subclaim}\label{subclaim:clean-helps}
        If $P_{L \rightarrow j}$ contains the end of a clean stage, then $$\E[\|\embed[i]-\embed[j]\|_1] \ge \Omega(1) \cdot \E[\|\embed[i]\|_1].$$
    \end{subclaim}
    \begin{proof}
        Note how, because there is a clean stage ending in $P_{L \rightarrow j}$, the only nonzero coordinates of $\embed[j]$ must be coordinates hashed into by one of the $\le \lb$ build edges after the \textit{last }clean. Note also that these hash values are independent of $\embed[i]$, and there are at most $\lb = 4 \log(n) \le \frac{|H|}{2}$ such coordinates. Let $Z_k$ denote the event that none of these build edges hash into the $k^{\text{th}}$ coordinate. Observe that by the union bound, $\Pr[Z_k] \ge \frac12$. Conditioned on $Z_k$, observe that $\embed[i](k)-\embed[j](k)=\embed[i](k)$. Accordingly,

        \begin{align}
            \E[\|\embed[i]-\embed[j]\|_1] &= \sum_{k=1}^{H}\E[|\embed[i](k)-\embed[j](k)|] \\
            & \ge \sum_{k=1}^H \Pr(Z_k) \cdot \E\left[|\embed[i](k)-\embed[j](k)| ~\bigg|~ Z_k\right] \\
            & = \sum_{k=1}^H \Pr(Z_k) \cdot \E\left[|\embed[i](k)| ~\bigg|~ Z_k\right] \\
            & = \sum_{k=1}^H \Pr(Z_k) \cdot \E[\|\embed[i](k)\|_1] \qquad(\text{independence})\\
            & \ge \sum_{k=1}^H \frac{1}{2} \cdot E[|\embed[i](k)|] \\
            & = \frac{1}{2} \cdot \E[\|\embed[i]\|_1].
        \end{align}
    \end{proof}

    For (iii), the following lets us say that the expected norm of any node's embedding is within a constant factor of its cap. Note how this would not be true for the root $r$ if it had a nonzero cap and we had just initialized the root's embedding as all zeros. This is the reason behind our initialization with an extra $r_0$ node.
    \begin{subclaim}\label{subclaim:big-norm}
        $\E[\|\embed[i]\|_1] = \Omega(1) \cdot M(i)$.
    \end{subclaim}
    \begin{proof}
        This follows from invoking \Cref{subclaim:leg} with $x=x_i$ and $y=r_0$ (and thus, $L=LCA(x_i, r_0)=r_0$), and recalling that $\embed[r_0] = 0^{|H|}$:
        \begin{align}
            \E[\|\embed[i]\|_1] & = \E[\|\embed[i]-\embed[r_0]\|_1]\\
            & \ge \Omega(1) \cdot \min(d(r_0,x),M(x))\\
            &= \Omega(1) \cdot \min(2M(r)+d(r, x_i),M(x)) \\
            & \ge \Omega(1) \cdot \min(2 M(r) + |M(r) - M(x)|,M(x)) \qquad (\text{by Lipschitzness})\\
            & \ge \Omega(1) \cdot M(x),
        \end{align}
        where the last inequality follows because $2M(r)+|M(r)-M(x)| \ge \frac{M(x)}{2}$, which can be seen by considering two cases $M(r) \ge \frac{M(x)}{2}$ and $M(r) < \frac{M(x)}{2}$.
    \end{proof}
    Thus, as \Cref{subclaim:must-clean} implies the condition required by \Cref{subclaim:clean-helps}, combining with \Cref{subclaim:big-norm} yields $\E[\|\embed[i]-\embed[j]\|_1] \ge \Omega(1) \cdot M(i) \ge \Omega(1) \cdot \dlcap{M}(i,j)$.
    Thus, we have proven part(2) of \Cref{lemma:tree-lipschitz-cap-lb} in its entirety.
\end{proof}
